class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        def kadane(a):
            b = float('-inf'); c = 0
            for x in a:
                c = max(c, 0) + x; b = max(b, c)
            return b
        ans = kadane(nums)
        for x in set(nums):
            ans = max(ans, kadane([v for v in nums if v != x]))
        return ans

