        long long ans = kadane(nums);
        unordered_set<int> vals(nums.begin(), nums.end());
        vector<int> f;
        for (int x : vals) {
            f.clear();
            for (int v : nums) if (v != x) f.push_back(v);
            ans = max(ans, kadane(f));
        }
        return ans;
    }
};

