class Solution {
    private long kadane(List<Integer> a) {
        long b = Long.MIN_VALUE, c = 0;
        for (int x : a) { c = Math.max(c, 0) + x; b = Math.max(b, c); }
        return b;
    }
    public long maxSubarraySum(int[] nums) {
        List<Integer> orig = new ArrayList<>();
        for (int v : nums) orig.add(v);
        long ans = kadane(orig);
        Set<Integer> vals = new HashSet<>(orig);
        List<Integer> f = new ArrayList<>();
        for (int x : vals) {
            f.clear();
            for (int v : nums) if (v != x) f.add(v);
            ans = Math.max(ans, kadane(f));
        }
        return ans;
    }
}

