class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        NEG = float('-inf')
        def kadane(a):
            b = NEG; c = 0
            for x in a:
                c = max(c, 0) + x; b = max(b, c)
            return b
        ans = kadane(nums)
        occ = defaultdict(list)
        for i, x in enumerate(nums): occ[x].append(i)
        for ids in occ.values():
            bnds = [-1] + ids + [len(nums)]
            tot = pre = suf = 0; best = NEG; first = True
            for gi in range(len(bnds) - 1):
                l, r = bnds[gi] + 1, bnds[gi + 1]
                if l >= r: continue
                t = 0; p = NEG; sf = NEG; bs = NEG
                for v in nums[l:r]:
                    t += v; p = max(p, t); sf = max(sf, 0) + v; bs = max(bs, sf)
                if first:
                    tot, pre, suf, best = t, p, sf, bs; first = False
                else:
                    best = max(best, bs, suf + p)
                    pre = max(pre, tot + p)
                    suf = max(sf, t + suf)
                    tot += t
            ans = max(ans, best)
        return ans

