class Solution {
public:
    long long maxSubarraySum(vector<int>& nums) {
        const long long NEG = LLONG_MIN / 2;
        long long ans = NEG, c = 0;
        for (int x : nums) { c = max(c, 0LL) + x; ans = max(ans, c); }
        unordered_map<int, vector<int>> occ;
        for (int i = 0; i < (int)nums.size(); i++) occ[nums[i]].push_back(i);
        for (auto& [x, ids] : occ) {
            vector<int> bnds; bnds.push_back(-1);
            for (int id : ids) bnds.push_back(id);
            bnds.push_back(nums.size());
            long long tot = 0, pre = 0, suf = 0, best = NEG; bool first = true;
            for (int gi = 0; gi + 1 < (int)bnds.size(); gi++) {
                int l = bnds[gi] + 1, r = bnds[gi + 1];
                if (l >= r) continue;
                long long t = 0, p = NEG, sf = NEG, bs = NEG;
                for (int i2 = l; i2 < r; i2++) {
                    t += nums[i2]; p = max(p, t);
                    sf = max(sf, 0LL) + nums[i2]; bs = max(bs, sf);
                }
                if (first) { tot = t; pre = p; suf = sf; best = bs; first = false; }
                else {
                    best = max({best, bs, suf + p});
                    pre = max(pre, tot + p);
                    suf = max(sf, t + suf);
                    tot += t;
                }
            }
            ans = max(ans, best);
        }
        return ans;
    }
};

