class Solution {
    public long maxSubarraySum(int[] nums) {
        long NEG = Long.MIN_VALUE / 2, ans = NEG, c = 0;
        for (int x : nums) { c = Math.max(c, 0) + x; ans = Math.max(ans, c); }
        Map<Integer, List<Integer>> occ = new HashMap<>();
        for (int i = 0; i < nums.length; i++) occ.computeIfAbsent(nums[i], k -> new ArrayList<>()).add(i);
        for (List<Integer> ids : occ.values()) {
            List<Integer> bnds = new ArrayList<>(); bnds.add(-1); bnds.addAll(ids); bnds.add(nums.length);
            long tot = 0, pre = 0, suf = 0, best = NEG; boolean first = true;
            for (int gi = 0; gi + 1 < bnds.size(); gi++) {
                int l = bnds.get(gi) + 1, r = bnds.get(gi + 1);
                if (l >= r) continue;
                long t = 0, p = NEG, sf = NEG, bs = NEG;
                for (int i2 = l; i2 < r; i2++) {
                    t += nums[i2]; p = Math.max(p, t);
                    sf = Math.max(sf, 0) + nums[i2]; bs = Math.max(bs, sf);
                }
                if (first) { tot = t; pre = p; suf = sf; best = bs; first = false; }
                else {
                    best = Math.max(Math.max(best, bs), suf + p);
                    pre = Math.max(pre, tot + p);
                    suf = Math.max(sf, t + suf);
                    tot += t;
                }
            }
            ans = Math.max(ans, best);
        }
        return ans;
    }
}

